use anyhow::Result;
use clap::ArgMatches;
use std::path::PathBuf;

#[derive(Clone)]
pub struct Config {
    pub pattern: Option<String>,
    pub paths: Vec<PathBuf>,
    pub ignore_case: bool,
    pub case_sensitive: bool,
    pub smart_case: bool,
    pub invert_match: bool,
    pub count: bool,
    pub only_matching: bool,
    pub line_number: bool,
    pub files_with_matches: bool,
    pub files: bool,
    pub word_regexp: bool,
    pub line_regexp: bool,
    pub max_count: Option<usize>,
    pub hidden: bool,
    pub no_ignore: bool,
    pub fixed_strings: bool,
    pub text: bool,
    pub multiline: bool,
    pub threads: Option<usize>,
    pub show_files: bool,
    pub patterns: Vec<String>,
}

impl Config {
    pub fn from_matches(matches: &ArgMatches) -> Result<Self> {
        // Collect all patterns
        let mut patterns = Vec::new();

        if let Some(pattern) = matches.get_one::<String>("PATTERN") {
            patterns.push(pattern.clone());
        }

        if let Some(regexp_patterns) = matches.get_many::<String>("regexp") {
            for p in regexp_patterns {
                patterns.push(p.clone());
            }
        }

        // Get paths
        let mut paths: Vec<PathBuf> = Vec::new();
        if let Some(path_args) = matches.get_many::<String>("PATH") {
            for p in path_args {
                paths.push(PathBuf::from(p));
            }
        }

        // If no paths specified, use current directory
        if paths.is_empty() && !patterns.is_empty() {
            paths.push(PathBuf::from("."));
        }

        let show_files = matches.get_flag("files");

        Ok(Config {
            pattern: if patterns.len() == 1 { Some(patterns[0].clone()) } else { None },
            paths,
            ignore_case: matches.get_flag("ignore-case"),
            case_sensitive: matches.get_flag("case-sensitive"),
            smart_case: matches.get_flag("smart-case"),
            invert_match: matches.get_flag("invert-match"),
            count: matches.get_flag("count"),
            only_matching: matches.get_flag("only-matching"),
            line_number: matches.get_flag("line-number"),
            files_with_matches: matches.get_flag("files-with-matches"),
            files: show_files,
            word_regexp: matches.get_flag("word-regexp"),
            line_regexp: matches.get_flag("line-regexp"),
            max_count: matches.get_one::<String>("max-count").and_then(|s| s.parse().ok()),
            hidden: matches.get_flag("hidden"),
            no_ignore: matches.get_flag("no-ignore"),
            fixed_strings: matches.get_flag("fixed-strings"),
            text: matches.get_flag("text"),
            multiline: matches.get_flag("multiline"),
            threads: matches.get_one::<String>("threads").and_then(|s| s.parse().ok()),
            show_files,
            patterns,
        })
    }
}
EOF

