use std::io::Write;
use colored::*;
use crate::config::Config;

pub struct Printer {
    config: Config,
}

impl Printer {
    pub fn new(config: Config) -> Self {
        Printer { config }
    }

    pub fn print_result(&self, path: &str, line_num: Option<usize>, line: &str, matches: Vec<(usize, usize)>) {
        let mut output = String::new();

        if self.config.count {
            // Don't print anything here, handle in searcher
            return;
        }

        if self.config.files_with_matches || self.config.show_files {
            println!("{}", path);
            return;
        }

        // Add path
        if path != "-" {
            output.push_str(&path.cyan().to_string());
            output.push(':');
        }

        // Add line number
        if self.config.line_number && path != "-" {
            output.push_str(&line_num.unwrap_or(0).to_string().green().to_string());
            output.push(':');
        }

        if self.config.only_matching {
            if path != "-" {
                for (start, end) in matches {
                    print!("{}", output);
                    println!("{}", &line[start..end].red().to_string());
                    output.clear();
                }
            } else {
                for (start, end) in matches {
                    println!("{}", &line[start..end]);
                }
            }
        } else {
            if !matches.is_empty() && !line.is_empty() {
                output.push_str(&colorize_line(line, &matches));
            } else {
                output.push_str(line);
            }
            println!("{}", output);
        }
    }

    pub fn print_file_path(&self, path: &str) {
        println!("{}", path);
    }
}

fn colorize_line(line: &str, matches: &[(usize, usize)]) -> String {
    let mut result = String::new();
    let mut last_end = 0;

    for (start, end) in matches {
        if start >= last_end {
            result.push_str(&line[last_end..*start]);
            result.push_str(&line[*start..*end].red().to_string());
            last_end = *end;
        }
    }

    result.push_str(&line[last_end..]);
    result
}
EOF

