use anyhow::Result;
use regex::RegexBuilder;
use std::fs::{self, File};
use std::io::{BufRead, BufReader, Read};
use std::path::PathBuf;
use walkdir::WalkDir;
use ignore::WalkBuilder;

use crate::config::Config;
use crate::printer::Printer;

pub struct Searcher {
    config: Config,
    printer: Printer,
}

impl Searcher {
    pub fn new(config: Config) -> Result<Self> {
        let printer = Printer::new(config.clone());
        Ok(Searcher { config, printer })
    }

    pub fn run(&mut self) -> Result<()> {
        // Handle special modes
        if self.config.show_files {
            self.list_files()?;
            return Ok(());
        }

        let patterns = if self.config.patterns.is_empty() {
            vec!["".to_string()]
        } else {
            self.config.patterns.clone()
        };

        // Check if we're reading from stdin
        let stdin = std::io::stdin();
        let stdin_lock = stdin.lock();
        if !atty::is(atty::Stream::Stdin) || self.config.paths.is_empty() {
            // Read from stdin
            return self.search_reader(BufReader::new(stdin_lock), "<stdin>", &patterns);
        }

        // Search files
        for path in &self.config.paths {
            self.search_path(path, &patterns)?;
        }

        Ok(())
    }

    fn list_files(&self) -> Result<()> {
        let walker = if self.config.no_ignore {
            WalkDir::new(".")
        } else {
            WalkDir::new(".")
        };

        for entry in walker {
            let entry = entry?;
            let path = entry.path();

            if path.is_file() {
                println!("{}", path.display());
            }
        }

        Ok(())
    }

    fn search_path(&mut self, path: &PathBuf, patterns: &[String]) -> Result<()> {
        if path.is_file() {
            self.search_file(path, patterns)?;
        } else if path.is_dir() {
            self.search_dir(path, patterns)?;
        }

        Ok(())
    }

    fn search_file(&mut self, path: &PathBuf, patterns: &[String]) -> Result<()> {
        let file = File::open(path)?;
        let reader = BufReader::new(file);
        self.search_reader(reader, &path.display().to_string(), patterns)?;
        Ok(())
    }

    fn search_dir(&mut self, dir: &PathBuf, patterns: &[String]) -> Result<()> {
        let mut builder = WalkBuilder::new(dir);
        builder.hidden(!self.config.hidden);
        builder.ignore(!self.config.no_ignore);
        builder.git_ignore(!self.config.no_ignore);

        let walker = builder.build();

        for entry in walker {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_file() && !path.starts_with("./.git") {
                    if let Err(_) = self.search_file(&path.to_path_buf(), patterns) {
                        // Skip files we can't read
                        continue;
                    }
                }
            }
        }

        Ok(())
    }

    fn search_reader<R: Read>(&mut self, reader: R, path: &str, patterns: &[String]) -> Result<()> {
        let buf_reader = BufReader::new(reader);
        let mut line_num = 0;
        let mut count = 0;

        // Compile regex
        let regex = if self.config.fixed_strings {
            // For fixed strings, escape all special regex characters
            if patterns.is_empty() || patterns[0].is_empty() {
                None
            } else {
                let escaped = regex::escape(&patterns[0]);
                let mut builder = RegexBuilder::new(&escaped);
                builder.case_insensitive(self.config.ignore_case);
                builder.multi_line(self.config.multiline);
                Some(builder.build()?)
            }
        } else {
            if patterns.is_empty() || patterns[0].is_empty() {
                None
            } else {
                let mut pattern = patterns[0].clone();
                if self.config.word_regexp {
                    pattern = format!(r"\b{}\b", pattern);
                }
                if self.config.line_regexp {
                    pattern = format!("^{}$", pattern);
                }

                let mut builder = RegexBuilder::new(&pattern);
                builder.case_insensitive(self.config.ignore_case);
                builder.multi_line(self.config.multiline);
                builder.dot_matches_new_line(false);
