fn run(config: &Config) -> Result<(), String> {
    // Handle --files mode
    if config.show_files {
        list_files(&config)?;
        return Ok(());
    }

    // Check if reading from stdin
    let mut patterns = Vec::new();
    if let Some(ref p) = config.pattern {
        patterns.push(p.clone());
    }
    patterns.extend(config.patterns.clone());

    if patterns.is_empty() {
        return Err("No pattern provided".to_string());
    }

    // Check if we should read from stdin
    let stdin = io::stdin();
    if !stdin.is_terminal() && config.paths.is_empty() {
        // Read from stdin
        search_reader(&stdin.lock(), "<stdin>", &patterns, config)?;
        return Ok(());
    }

    // Search files
    if config.paths.is_empty() {
        search_path(&PathBuf::from("."), &patterns, config)?;
    } else {
        for path in &config.paths {
            search_path(path, &patterns, config)?;
        }
    }

    Ok(())
}

fn list_files(config: &Config) -> Result<(), String> {
    let path = if config.paths.is_empty() {
        PathBuf::from(".")
    } else {
        config.paths[0].clone()
    };

    list_files_recursive(&path, config)?;
    Ok(())
}

fn list_files_recursive(dir: &PathBuf, config: &Config) -> Result<(), String> {
    let entries = fs::read_dir(dir).map_err(|e| e.to_string())?;

    for entry in entries {
        let entry = entry.map_err(|e| e.to_string())?;
        let path = entry.path();

        if path.is_file() {
            println!("{}", path.display());
        } else if path.is_dir() && (config.hidden || !is_hidden(&path)) {
            if !should_ignore(&path, config) {
                list_files_recursive(&path, config)?;
            }
        }
    }

    Ok(())
}

fn search_path(path: &PathBuf, patterns: &[String], config: &Config) -> Result<(), String> {
    if path.is_file() {
        search_file(path, patterns, config)?;
    } else if path.is_dir() {
        search_dir(path, patterns, config)?;
    }

    Ok(())
}

fn search_file(path: &PathBuf, patterns: &[String], config: &Config) -> Result<(), String> {
    let file = File::open(path).map_err(|e| e.to_string())?;
    let reader = BufReader::new(file);
    search_reader(&reader, &path.display().to_string(), patterns, config)?;
    Ok(())
}

fn search_dir(dir: &PathBuf, patterns: &[String], config: &Config) -> Result<(), String> {
    let entries = fs::read_dir(dir).map_err(|e| e.to_string())?;

    for entry in entries {
        let entry = entry.map_err(|e| e.to_string())?;
        let path = entry.path();

        if path.is_file() {
            if config.hidden || !is_hidden(&path) {
                if !should_ignore(&path, config) {
                    let _ = search_file(&path, patterns, config);
                }
            }
        } else if path.is_dir() {
            if config.hidden || !is_hidden(&path) {
                if !should_ignore(&path, config) {
                    let _ = search_dir(&path, patterns, config);
                }
            }
        }
    }

    Ok(())
}

fn search_reader<R: Read>(reader: &mut R, path: &str, patterns: &[String], config: &Config) -> Result<(), String> {
    let buf_reader = BufReader::new(reader);
    let mut line_num = 0;
    let mut count = 0;
    let mut has_match = false;

    let pattern = if patterns.is_empty() { "" } else { &patterns[0] };

    for line_result in buf_reader.lines() {
        let line = line_result.map_err(|e| e.to_string())?;
        line_num += 1;

        let matches = find_matches(&line, pattern, config);
        let is_match = !matches.is_empty();

        let should_print = if config.invert_match { !is_match } else { is_match };

        if should_print {
            has_match = true;
            if config.count {
                count += 1;
            } else if config.files_with_matches {
                println!("{}", path);
                break;
            } else if config.only_matching {
                for (start, end) in matches {
                    print_result(path, Some(line_num), &line[start..end], config, false);
                }
            } else {
                print_result(path, Some(line_num), &line, config, true);
            }

            if let Some(max) = config.max_count {
                if count >= max {
                    break;
                }
            }
        }
    }

    if config.count {
        if path == "<stdin>" {
            println!("{}", count);
        } else {
            println!("{}:{}", path, count);
        }
    }

    Ok(())
}

fn find_matches(text: &str, pattern: &str, config: &Config) -> Vec<(usize, usize)> {
    if pattern.is_empty() {
        return vec![];
    }

    let mut matches = Vec::new();

    if config.fixed_strings {
        // Literal string search
        let pattern_lower = if config.ignore_case {
            pattern.to_lowercase()
        } else {
            pattern.to_string()
        };

        let text_search = if config.ignore_case {
            text.to_lowercase()
        } else {
            text.to_string()
        };

        let mut start = 0;
        while let Some(pos) = text_search[start..].find(&pattern_lower) {
            let actual_pos = start + pos;
            matches.push((actual_pos, actual_pos + pattern.len()));
            start = actual_pos + 1;
        }
    } else {
        // Regex search (simplified - just basic pattern matching)
        matches = regex_search(text, pattern, config);
    }

    matches
}

fn regex_search(text: &str, pattern: &str, config: &Config) -> Vec<(usize, usize)> {
    // Simplified regex implementation
    let pattern = if config.word_regexp {
        format!(r"\b{}\b", pattern)
    } else if config.line_regexp {
        format!("^{}$", pattern)
    } else {
        pattern.to_string()
    };

    let mut pattern = pattern.clone();

    // Very basic pattern matching
    let text_search = if config.ignore_case {
        text.to_lowercase()
    } else {
        text.to_string()
    };

    let pattern_lower = if config.ignore_case {
        pattern.to_lowercase()
    } else {
        pattern.clone()
    };

    // Handle basic patterns like "test", "test.", etc.
    let mut matches = Vec::new();

    // Check if pattern is simple (no regex metacharacters)
    if !has_regex_metacharacters(&pattern) {
        // Simple string search
        let mut start = 0;
        while let Some(pos) = text_search[start..].find(&pattern_lower) {
            let actual_pos = start + pos;
            matches.push((actual_pos, actual_pos + pattern.len()));
            start = actual_pos + 1;
        }
    } else {
        // Try to handle basic regex patterns
        matches = simple_regex_match(&text_search, &pattern_lower, text);
    }

    matches
}

fn has_regex_metacharacters(pattern: &str) -> bool {
    pattern.contains('.') || pattern.contains('*') || pattern.contains('+') || 
    pattern.contains('?') || pattern.contains('|') || pattern.contains('[') ||
    pattern.contains(']') || pattern.contains('(') || pattern.contains(')')
}

fn simple_regex_match(text: &str, pattern: &str, original_text: &str) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();

    // Handle simple patterns like "t..t" (with dots)
    if pattern.contains('.') {
        // t..t pattern
        for i in 0..text.len() {
            let mut pattern_idx = 0;
            let mut text_idx = i;

            while pattern_idx < pattern.len() && text_idx < text.len() {
                if pattern_idx < pattern.len() && pattern.chars().nth(pattern_idx) == Some('.') {
                    text_idx += 1;
                    pattern_idx += 1;
                } else if pattern_idx < pattern.len() && text_idx < text.len() && 
                          pattern.chars().nth(pattern_idx) == text.chars().nth(text_idx) {
                    text_idx += 1;
                    pattern_idx += 1;
                } else {
                    break;
                }
            }

            if pattern_idx == pattern.len() {
                matches.push((i, text_idx));
            }
        }
    } else {
        // Try simple string match
        let mut start = 0;
        while let Some(pos) = text[start..].find(pattern) {
            let actual_pos = start + pos;
            matches.push((actual_pos, actual_pos + pattern.len()));
            start = actual_pos + 1;
        }
    }

    matches
}

fn print_result(path: &str, line_num: Option<usize>, content: &str, config: &Config, is_full_line: bool) {
    let mut output = String::new();

    if path != "<stdin>" {
        output.push_str(path);
        output.push(':');
    }

    if config.line_number && path != "<stdin>" {
        if let Some(num) = line_num {
            output.push_str(&num.to_string());
            output.push(':');
        }
    }

    output.push_str(content);
