#[derive(Clone, Debug)]
struct Config {
    pattern: Option<String>,
    patterns: Vec<String>,
    paths: Vec<PathBuf>,
    ignore_case: bool,
    case_sensitive: bool,
    smart_case: bool,
    invert_match: bool,
    count: bool,
    only_matching: bool,
