#[derive(Clone, Debug)]
struct Config {
    pattern: Option<String>,
    patterns: Vec<String>,
    paths: Vec<PathBuf>,
    ignore_case: bool,
    case_sensitive: bool,
    smart_case: bool,
    invert_match: bool,
    count: bool,
    only_matching: bool,
    line_number: bool,
    files_with_matches: bool,
    show_files: bool,
    word_regexp: bool,
    line_regexp: bool,
    max_count: Option<usize>,
    hidden: bool,
    no_ignore: bool,
    fixed_strings: bool,
    text: bool,
    multiline: bool,
}

fn parse_args(args: &[String]) -> Result<Config, String> {
    let mut pattern = None;
    let mut patterns = Vec::new();
    let mut paths = Vec::new();
    let mut ignore_case = false;
    let mut case_sensitive = false;
    let mut smart_case = false;
    let mut invert_match = false;
    let mut count = false;
    let mut only_matching = false;
    let mut line_number = false;
    let mut files_with_matches = false;
    let mut show_files = false;
    let mut word_regexp = false;
    let mut line_regexp = false;
    let mut max_count = None;
    let mut hidden = false;
    let mut no_ignore = false;
    let mut fixed_strings = false;
    let mut text = false;
    let mut multiline = false;

    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];

        if arg == "--" {
            i += 1;
            if i < args.len() && pattern.is_none() {
                pattern = Some(args[i].clone());
                i += 1;
            }
            while i < args.len() {
                paths.push(PathBuf::from(&args[i]));
                i += 1;
            }
            break;
        } else if arg == "-c" || arg == "--count" {
            count = true;
            i += 1;
        } else if arg == "-o" || arg == "--only-matching" {
            only_matching = true;
            i += 1;
        } else if arg == "-n" || arg == "--line-number" {
            line_number = true;
            i += 1;
        } else if arg == "-l" || arg == "--files-with-matches" {
            files_with_matches = true;
            i += 1;
        } else if arg == "-i" || arg == "--ignore-case" {
            ignore_case = true;
            i += 1;
        } else if arg == "-s" || arg == "--case-sensitive" {
            case_sensitive = true;
            i += 1;
        } else if arg == "-S" || arg == "--smart-case" {
            smart_case = true;
            i += 1;
        } else if arg == "-v" || arg == "--invert-match" {
            invert_match = true;
            i += 1;
        } else if arg == "-F" || arg == "--fixed-strings" {
            fixed_strings = true;
            i += 1;
        } else if arg == "-w" || arg == "--word-regexp" {
            word_regexp = true;
            i += 1;
        } else if arg == "-x" || arg == "--line-regexp" {
            line_regexp = true;
            i += 1;
        } else if arg == "-a" || arg == "--text" {
            text = true;
            i += 1;
        } else if arg == "-U" || arg == "--multiline" {
            multiline = true;
            i += 1;
        } else if arg == "--hidden" || arg == "-." {
            hidden = true;
            i += 1;
        } else if arg == "--no-ignore" {
            no_ignore = true;
            i += 1;
        } else if arg == "--files" {
            show_files = true;
            i += 1;
        } else if arg == "-e" || arg == "--regexp" {
            i += 1;
            if i >= args.len() {
                return Err("Expected pattern after -e".to_string());
            }
            patterns.push(args[i].clone());
            i += 1;
        } else if arg == "-m" || arg == "--max-count" {
            i += 1;
            if i >= args.len() {
                return Err("Expected number after -m".to_string());
            }
            max_count = Some(args[i].parse().map_err(|_| "Invalid number")?);
            i += 1;
        } else if arg.starts_with('-') {
            return Err(format!("Unknown option: {}", arg));
        } else {
            // First non-option is the pattern (if no pattern or patterns yet)
            if pattern.is_none() && patterns.is_empty() {
                pattern = Some(arg.clone());
            } else {
                paths.push(PathBuf::from(arg));
            }
            i += 1;
        }
    }

    Ok(Config {
        pattern,
        patterns,
        paths,
        ignore_case,
        case_sensitive,
        smart_case,
        invert_match,
        count,
        only_matching,
        line_number,
        files_with_matches,
        show_files,
        word_regexp,
        line_regexp,
        max_count,
        hidden,
        no_ignore,
        fixed_strings,
        text,
        multiline,
    })
}

fn run(config: &Config) -> Result<(), String> {
    // Handle --files mode
    if config.show_files {
        list_files(&config)?;
        return Ok(());
    }

    // Collect patterns
    let mut patterns = Vec::new();
    if let Some(ref p) = config.pattern {
        patterns.push(p.clone());
    }
    patterns.extend(config.patterns.clone());

    if patterns.is_empty() {
        return Err("No pattern provided".to_string());
    }

    // Determine if we should read from stdin or search files
    // If no paths given, try to read from stdin. If stdin is empty/unavailable, search filesystem
    if config.paths.is_empty() {
        let stdin = io::stdin();

        // Try to read a byte in a non-blocking way to see if there's data
        match try_read_stdin_nonblocking() {
            Some(first_byte) => {
                // stdin has data, read it all
                let mut all_data = vec![first_byte];
                stdin.lock().read_to_end(&mut all_data).ok();
                let reader = std::io::Cursor::new(all_data);
                let mut buf_reader = BufReader::new(reader);
                search_reader(&mut buf_reader, "<stdin>", &patterns, config, false)?;
            }
            None => {
                // No stdin data, search filesystem
                search_path(&PathBuf::from("."), &patterns, config, true)?;
            }
        }
    } else if config.paths.len() == 1 && config.paths[0].is_file() {
        // Single file - don't show path
        search_file(&config.paths[0], &patterns, config, false)?;
    } else {
        // Multiple paths or a directory - show paths
        for path in &config.paths {
            search_path(path, &patterns, config, true)?;
        }
    }

    Ok(())
}

fn try_read_stdin_nonblocking() -> Option<u8> {
    use std::os::unix::io::AsRawFd;
    use std::os::unix::io::RawFd;

    let stdin = io::stdin();
    let fd = stdin.as_raw_fd();

    // Try to get the current flags
    unsafe {
        let mut flags = libc::fcntl(fd, libc::F_GETFL);
        if flags == -1 {
            return None;
        }

        // Set non-blocking
        flags |= libc::O_NONBLOCK;
        if libc::fcntl(fd, libc::F_SETFL, flags) == -1 {
            return None;
        }

        // Try to read one byte
        let mut buf: u8 = 0;
        let n = libc::read(fd, &mut buf as *mut u8 as *mut libc::c_void, 1);

        // Restore blocking mode
        flags &= !libc::O_NONBLOCK;
        libc::fcntl(fd, libc::F_SETFL, flags);

        if n == 1 {
            Some(buf)
        } else {
            None
        }
    }
}

fn list_files(config: &Config) -> Result<(), String> {
    let path = if config.paths.is_empty() {
        PathBuf::from(".")
    } else {
        config.paths[0].clone()
    };

    list_files_recursive(&path, config)?;
    Ok(())
}

fn list_files_recursive(dir: &PathBuf, config: &Config) -> Result<(), String> {
    let entries = fs::read_dir(dir).map_err(|e| e.to_string())?;

    for entry in entries {
        let entry = entry.map_err(|e| e.to_string())?;
        let path = entry.path();

        if path.is_file() {
            println!("{}", path.display());
        } else if path.is_dir() && (config.hidden || !is_hidden(&path)) {
            if !should_ignore(&path, config) {
                list_files_recursive(&path, config)?;
            }
        }
    }

    Ok(())
}

fn search_path(path: &PathBuf, patterns: &[String], config: &Config, show_path: bool) -> Result<(), String> {
    if path.is_file() {
        search_file(path, patterns, config, show_path)?;
    } else if path.is_dir() {
        search_dir(path, patterns, config, show_path)?;
    }

    Ok(())
}

fn search_file(path: &PathBuf, patterns: &[String], config: &Config, show_path: bool) -> Result<(), String> {
    let file = File::open(path).map_err(|e| e.to_string())?;
    let mut reader = BufReader::new(file);
    search_reader(&mut reader, &path.display().to_string(), patterns, config, show_path)?;
