fn run(config: &Config) -> Result<(), String> {
    // Handle --files mode
    if config.show_files {
        list_files(&config)?;
        return Ok(());
    }

    // Collect patterns
    let mut patterns = Vec::new();
    if let Some(ref p) = config.pattern {
        patterns.push(p.clone());
    }
    patterns.extend(config.patterns.clone());

    if patterns.is_empty() {
        return Err("No pattern provided".to_string());
    }

    // Determine if we should read from stdin or search files
    // If no paths given, try to read from stdin. If stdin is empty/unavailable, search filesystem
    if config.paths.is_empty() {
        let stdin = io::stdin();

        // Try to read a byte in a non-blocking way to see if there's data
        match try_read_stdin_nonblocking() {
            Some(first_byte) => {
                // stdin has data, read it all
                let mut all_data = vec![first_byte];
                stdin.lock().read_to_end(&mut all_data).ok();
                let reader = std::io::Cursor::new(all_data);
                let mut buf_reader = BufReader::new(reader);
                search_reader(&mut buf_reader, "<stdin>", &patterns, config, false)?;
            }
            None => {
                // No stdin data, search filesystem
                search_path(&PathBuf::from("."), &patterns, config, true)?;
            }
        }
    } else if config.paths.len() == 1 && config.paths[0].is_file() {
        // Single file - don't show path
        search_file(&config.paths[0], &patterns, config, false)?;
    } else {
        // Multiple paths or a directory - show paths
        for path in &config.paths {
            search_path(path, &patterns, config, true)?;
        }
    }

    Ok(())
}

fn try_read_stdin_nonblocking() -> Option<u8> {
    use std::os::unix::io::AsRawFd;
    use std::os::unix::io::RawFd;

    let stdin = io::stdin();
    let fd = stdin.as_raw_fd();

    // Try to get the current flags
    unsafe {
        let mut flags = libc::fcntl(fd, libc::F_GETFL);
        if flags == -1 {
            return None;
        }

        // Set non-blocking
        flags |= libc::O_NONBLOCK;
        if libc::fcntl(fd, libc::F_SETFL, flags) == -1 {
            return None;
        }

        // Try to read one byte
        let mut buf: u8 = 0;
        let n = libc::read(fd, &mut buf as *mut u8 as *mut libc::c_void, 1);

        // Restore blocking mode
        flags &= !libc::O_NONBLOCK;
        libc::fcntl(fd, libc::F_SETFL, flags);

        if n == 1 {
            Some(buf)
        } else {
            None
        }
    }
}

fn list_files(config: &Config) -> Result<(), String> {
    let path = if config.paths.is_empty() {
        PathBuf::from(".")
    } else {
        config.paths[0].clone()
    };

    list_files_recursive(&path, config)?;
    Ok(())
}

fn list_files_recursive(dir: &PathBuf, config: &Config) -> Result<(), String> {
    let entries = fs::read_dir(dir).map_err(|e| e.to_string())?;

    for entry in entries {
        let entry = entry.map_err(|e| e.to_string())?;
        let path = entry.path();

        if path.is_file() {
            println!("{}", path.display());
        } else if path.is_dir() && (config.hidden || !is_hidden(&path)) {
            if !should_ignore(&path, config) {
                list_files_recursive(&path, config)?;
            }
        }
    }

    Ok(())
}

fn search_path(path: &PathBuf, patterns: &[String], config: &Config, show_path: bool) -> Result<(), String> {
    if path.is_file() {
        search_file(path, patterns, config, show_path)?;
    } else if path.is_dir() {
        search_dir(path, patterns, config, show_path)?;
    }

    Ok(())
}

fn search_file(path: &PathBuf, patterns: &[String], config: &Config, show_path: bool) -> Result<(), String> {
    let file = File::open(path).map_err(|e| e.to_string())?;
    let mut reader = BufReader::new(file);
    search_reader(&mut reader, &path.display().to_string(), patterns, config, show_path)?;
    Ok(())
}

fn search_dir(dir: &PathBuf, patterns: &[String], config: &Config, show_path: bool) -> Result<(), String> {
    let entries = fs::read_dir(dir).map_err(|e| e.to_string())?;

    for entry in entries {
        let entry = entry.map_err(|e| e.to_string())?;
        let path = entry.path();

        if path.is_file() {
            if config.hidden || !is_hidden(&path) {
                if !should_ignore(&path, config) {
                    let _ = search_file(&path, patterns, config, show_path);
                }
            }
        } else if path.is_dir() {
            if config.hidden || !is_hidden(&path) {
                if !should_ignore(&path, config) {
                    let _ = search_dir(&path, patterns, config, show_path);
                }
            }
        }
    }

    Ok(())
}

fn search_reader<R: Read>(reader: &mut R, path: &str, patterns: &[String], config: &Config, show_path: bool) -> Result<(), String> {
    let buf_reader = BufReader::new(reader);
    let mut line_num = 0;
    let mut count = 0;

    let pattern = if patterns.is_empty() { "" } else { &patterns[0] };

    for line_result in buf_reader.lines() {
        let line = line_result.map_err(|e| e.to_string())?;
        line_num += 1;

        let matches = find_matches(&line, pattern, config);
        let is_match = !matches.is_empty();

        let should_print = if config.invert_match { !is_match } else { is_match };

        if should_print {
            if config.count {
                count += 1;
            } else if config.files_with_matches {
                println!("{}", path);
                break;
            } else if config.only_matching {
                for (start, end) in matches {
                    print_result(path, Some(line_num), &line[start..end], config, show_path);
                }
            } else {
                print_result(path, Some(line_num), &line, config, show_path);
            }

            if let Some(max) = config.max_count {
                if count >= max {
                    break;
                }
            }
        }
    }

    if config.count {
        if show_path && path != "<stdin>" {
            println!("{}:{}", path, count);
        } else {
            println!("{}", count);
        }
    }

    Ok(())
}

fn find_matches(text: &str, pattern: &str, config: &Config) -> Vec<(usize, usize)> {
    if pattern.is_empty() {
        return vec![];
    }

    let mut matches = Vec::new();

    if config.fixed_strings {
        // Literal string search
        let pattern_lower = if config.ignore_case {
            pattern.to_lowercase()
        } else {
            pattern.to_string()
        };

        let text_search = if config.ignore_case {
            text.to_lowercase()
        } else {
            text.to_string()
        };

        let mut start = 0;
        while let Some(pos) = text_search[start..].find(&pattern_lower) {
            let actual_pos = start + pos;
            matches.push((actual_pos, actual_pos + pattern.len()));
            start = actual_pos + 1;
        }
    } else {
        // Regex search (simplified - just basic pattern matching)
        matches = regex_search(text, pattern, config);
    }

    matches
}

fn regex_search(text: &str, pattern: &str, config: &Config) -> Vec<(usize, usize)> {
    // Simplified regex implementation
    let pattern = if config.word_regexp {
        format!(r"\b{}\b", pattern)
    } else if config.line_regexp {
        format!("^{}$", pattern)
    } else {
        pattern.to_string()
    };

    // Very basic pattern matching
    let text_search = if config.ignore_case {
        text.to_lowercase()
    } else {
        text.to_string()
    };

    let pattern_lower = if config.ignore_case {
        pattern.to_lowercase()
    } else {
        pattern.clone()
    };

    // Handle basic patterns like "test", "test.", etc.
    let mut matches = Vec::new();

    // Check if pattern is simple (no regex metacharacters)
    if !has_regex_metacharacters(&pattern) {
        // Simple string search
        let mut start = 0;
        while let Some(pos) = text_search[start..].find(&pattern_lower) {
            let actual_pos = start + pos;
            matches.push((actual_pos, actual_pos + pattern.len()));
            start = actual_pos + 1;
        }
    } else {
        // Try to handle basic regex patterns
        matches = simple_regex_match(&text_search, &pattern_lower, text);
    }

    matches
}

fn has_regex_metacharacters(pattern: &str) -> bool {
    pattern.contains('.') || pattern.contains('*') || pattern.contains('+') || 
    pattern.contains('?') || pattern.contains('|') || pattern.contains('[') ||
    pattern.contains(']') || pattern.contains('(') || pattern.contains(')')
}

fn simple_regex_match(text: &str, pattern: &str, _original_text: &str) -> Vec<(usize, usize)> {
    let mut matches = Vec::new();

    // Handle simple patterns like "t..t" (with dots)
    if pattern.contains('.') {
